-- Conferência: quantas ainda ficam no card "A lançar · DDU"
-- (atendida e sem resposta externa) — deve cair para ~1.078.
select count(*) as a_lancar_ddu_restante
  from public.ddu_demandas
 where ativo = true
   and data_resposta_externa is null
   and (data_atendimento is not null or situacao in ('RESPONDIDA','FINALIZADA'));
